parameters.jsCode:
/**
 * Builds the arXiv RSS URL.
 *
 * The RSS host takes categories joined with "+":
 *   "cs.AI, cs.LG"  ->  https://rss.arxiv.org/rss/cs.AI+cs.LG
 *
 * This is a different service from export.arxiv.org/api/query, with its own
 * rate limits — which matters on n8n Cloud, where the outbound IP is shared
 * with every other tenant and the API's per-IP throttle can be tripped by
 * traffic that is not yours.
 *
 * It is also the better source for this job: the RSS feed *is* the day's
 * announcement list, so there is no date window to get right, no paging, and
 * every item carries an announce_type the API does not expose.
 */
const cfg = $input.first().json;

const categories = String(cfg.arxiv_categories)
  .split(',')
  .map((c) => c.trim())
  .filter(Boolean);

if (categories.length === 0) {
  throw new Error('Config.arxiv_categories is empty - there is nothing to fetch.');
}

return [
  {
    json: {
      ...cfg,
      rss_url: 'https://rss.arxiv.org/rss/' + categories.join('+'),
    },
  },
];

/**
 * Flattens one arXiv RSS feed into one n8n item per paper.
 *
 * The feed is RSS 2.0 with arxiv: and dc: extensions. Two shapes need care:
 *
 *  - The XML node runs with explicitArray = false, so a feed holding a single
 *    <item> arrives as an object rather than an array. That edge case is why
 *    this is a Code node and not a Split Out node.
 *  - mergeAttrs = true folds attributes into their parent, so an element that
 *    has both attributes and text — <guid isPermaLink="false">oai:…</guid> —
 *    becomes { isPermaLink: 'false', _: 'oai:…' } rather than a string.
 */
const channel = $input.first().json.rss?.channel ?? {};
const many = (v) => (Array.isArray(v) ? v : v == null ? [] : [v]);
const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
// Unwrap the { _: 'text', attr: '…' } form the XML node produces for elements
// that carry attributes alongside their text.
const text = (v) => clean(v && typeof v === 'object' ? v._ : v);

return many(channel.item).map((item) => {
  // guid: "oai:arXiv.org:2609.11955v1" -> id 2609.11955, version v1
  const guid = text(item.guid);
  const idWithVersion = guid.split(':').pop();
  const version = idWithVersion.match(/v(\d+)$/)?.[1];

  // description: "arXiv:2609.11955v1 Announce Type: new \nAbstract: <body>"
  const description = clean(item.description);
  const abstract = clean(description.split(/Abstract:\s*/s).slice(1).join('Abstract: ')) || description;

  const absUrl = text(item.link);
  const authors = text(item['dc:creator'])
    .split(/,\s*/)
    .map(clean)
    .filter(Boolean);
  const categories = many(item.category).map(text).filter(Boolean);

  return {
    json: {
      arxiv_id: idWithVersion.replace(/v\d+$/, ''),
      version: version ? 'v' + version : 'v1',
      // new: first announcement. cross: announced in another category first.
      // replace: a revision of a paper announced earlier - usually not news.
      announce_type: text(item['arxiv:announce_type']) || 'new',
      title: clean(item.title),
      abstract,
      authors,
      authors_line:
        authors.length > 6 ? authors.slice(0, 6).join(', ') + ' et al.' : authors.join(', '),
      primary_category: categories[0] ?? '',
      categories,
      // The RSS pubDate is the announcement date, shared by every item in the
      // feed - not the submission date the API reports.
      published: item.pubDate ? new Date(text(item.pubDate)).toISOString() : new Date().toISOString(),
      updated: '',
      abs_url: absUrl,
      pdf_url: absUrl.replace('/abs/', '/pdf/'),
      // Not carried by RSS; kept so the item shape matches what the prompt and
      // the Discord card already expect.
      comment: '',
      journal_ref: '',
    },
  };
});

/**
 * Splits the reader profile into wants and don't-wants, then packs every
 * concept and every abstract into one batch embedding request.
 *
 * Why the split: embeddings do not represent negation. "Not interested in
 * reinforcement learning for games" embeds close to "interested in
 * reinforcement learning for games" — the content words dominate and "not" is
 * a rounding error. Fold the whole profile into one vector and it faithfully
 * attracts everything the reader asked to avoid. So the halves are embedded
 * separately and the negative one is subtracted downstream.
 *
 * Classification is per fragment, not per line: "Ships production systems;
 * does not run large-scale pretraining" is a want and a don't-want in one
 * sentence, and the don't-want is the half that matters.
 */
const cfg = $('Config').first().json;
const papers = $input.all().map((i) => i.json);

const NEGATIVE_MARKERS = ['not interested', 'no interest', 'not relevant', 'uninterested', 'avoid', 'exclude', 'ignore'];
const POSITIVE_MARKERS = ['interested in', 'actively working', 'working on', 'focus', 'care about', 'looking for'];
const INLINE_NEGATIONS = ['does not', 'do not', "doesn't", "don't", 'rather than', 'instead of'];

// Left behind once a marker is stripped: "Not interested in: X" -> " in: X".
const LEADING_CONNECTOR = /^\s*(?:in|on|about|with|to|for|by)?\s*:?\s*/i;
const MARKER_RE = new RegExp('^.*(?:' + [...NEGATIVE_MARKERS, ...POSITIVE_MARKERS].join('|') + ')', 'i');

// One vector for "RAG, agents, evaluation" is a blurred average that matches
// none of them well. Three vectors, scored with a max, match each precisely.
const fragments = (text) =>
  String(text)
    .split(/[,;.\n]| and (?=[a-z])/)
    .map((p) => p.replace(/^[\s\t\-–—:()]+|[\s\t\-–—:()]+$/g, ''))
    // A letter has to be present, and 3 chars is the floor: "rag" and "agents"
    // are real entries in the vocabulary, and a longer minimum would silently
    // drop the reader's most important interests while appearing to work.
    .filter((p) => p.length >= 3 && /[a-z]/i.test(p));

const positive = [];
const negative = [];
let lineMode = positive;

for (const rawLine of String(cfg.research_profile ?? '').split('\n')) {
  const line = rawLine.trim();
  if (!line) continue;

  const lower = line.toLowerCase();
  // A heading sets the mode for this line and the ones that continue it, so a
  // wrapped "Not interested in:" list stays negative to its last item.
  if (NEGATIVE_MARKERS.some((m) => lower.includes(m))) lineMode = negative;
  else if (POSITIVE_MARKERS.some((m) => lower.includes(m))) lineMode = positive;

  const stripped = line.replace(MARKER_RE, '');
  const body = stripped !== line ? stripped.replace(LEADING_CONNECTOR, '') : line;

  for (const fragment of fragments(body || line)) {
    const inlineNegative = INLINE_NEGATIONS.some((neg) => fragment.toLowerCase().includes(neg));
    (inlineNegative ? negative : lineMode).push(fragment);
  }
}

const uniq = (xs) => [...new Set(xs)];
const pos = uniq(positive);
const neg = uniq(negative);

if (pos.length === 0 && neg.length === 0) {
  throw new Error('research_profile produced no usable concepts - check the Config node');
}

// batchEmbedContents takes at most 100 texts. Concepts come first because
// without them nothing can be scored at all; papers take whatever is left and
// any overflow keeps its chronological place further down.
const BATCH_LIMIT = 100;
const budget = Math.max(0, BATCH_LIMIT - pos.length - neg.length);
const embedded = papers.slice(0, budget);

// The title is repeated: it is the densest signal in the document, and a
// truncated abstract loses its tail first.
const paperText = (p) => `${String(p.title ?? '').trim()}\n\n${String(p.title ?? '').trim()}. ${String(p.abstract ?? '').trim()}`;

const texts = [...pos, ...neg, ...embedded.map(paperText)];
const model = 'models/' + String(cfg.embedding_model ?? 'text-embedding-004');

return [
  {
    json: {
      positive: pos,
      negative: neg,
      counts: { positive: pos.length, negative: neg.length, papers: embedded.length, skipped: papers.length - embedded.length },
      embedded_ids: embedded.map((p) => p.arxiv_id),
      payload: JSON.stringify({
        requests: texts.map((text) => ({ model, content: { parts: [{ text }] } })),
      }),
    },
  },
];

/**
 * Scores every paper against the profile and orders them, best first.
 *
 *   score = max cosine(paper, any positive concept)
 *         - w * max cosine(paper, any negative concept)
 *
 * Max rather than mean on both sides: a paper is relevant because it matches
 * one interest strongly, not because it is vaguely near the average of all of
 * them. The same logic makes a single strong hit against a negative concept
 * enough to sink it.
 *
 * This stage is an optimisation, not a dependency. If the embedding call
 * failed, was throttled, or answered with something unexpected, the papers
 * come back in the feed's own chronological order and the run continues. A
 * digest of the five newest is worse than a digest of the five best, and far
 * better than the silence of a failed run.
 */
const cfg = $('Config').first().json;
const papers = $('New and Cross-Lists Only').all().map((i) => i.json);
const meta = $('Split Profile').first().json;

const byRecency = (why) => papers.map((p) => ({ json: { ...p, ranked_by: why, rank_score: null } }));

const response = $input.first()?.json ?? {};
const vectors = Array.isArray(response.embeddings)
  ? response.embeddings.map((e) => e?.values).filter(Array.isArray)
  : null;

const expected = meta.counts.positive + meta.counts.negative + meta.counts.papers;
if (!vectors || vectors.length !== expected) {
  // A short or malformed response cannot be sliced safely - the concept and
  // paper vectors would be misaligned and every score silently wrong, which is
  // worse than not ranking at all.
  return byRecency('recency');
}

const norm = (v) => {
  let sum = 0;
  for (const x of v) sum += x * x;
  const n = Math.sqrt(sum);
  return n ? v.map((x) => x / n) : v;
};
const dot = (a, b) => {
  let s = 0;
  for (let i = 0; i < a.length; i++) s += a[i] * b[i];
  return s;
};

const nPos = meta.counts.positive;
const nNeg = meta.counts.negative;

const posVecs = vectors.slice(0, nPos).map(norm);
const negVecs = vectors.slice(nPos, nPos + nNeg).map(norm);
const paperVecs = vectors.slice(nPos + nNeg).map(norm);

const weight = Number(cfg.ranker_negative_weight ?? 0.5);

const scores = new Map();
meta.embedded_ids.forEach((arxivId, i) => {
  const v = paperVecs[i];

  let bestPos = 0;
  let matched = '';
  for (let j = 0; j < posVecs.length; j++) {
    const s = dot(v, posVecs[j]);
    if (s > bestPos || matched === '') {
      bestPos = s;
      matched = meta.positive[j];
    }
  }

  let bestNeg = 0;
  for (const nv of negVecs) bestNeg = Math.max(bestNeg, dot(v, nv));

  scores.set(arxivId, {
    score: Number((bestPos - weight * bestNeg).toFixed(6)),
    positive_similarity: Number(bestPos.toFixed(6)),
    negative_similarity: Number(bestNeg.toFixed(6)),
    matched,
  });
});

const ranked = papers.map((p) => {
  const hit = scores.get(p.arxiv_id);
  return {
    json: {
      ...p,
      rank_score: hit ? hit.score : null,
      rank_matched: hit ? hit.matched : '',
      rank_positive: hit ? hit.positive_similarity : null,
      rank_negative: hit ? hit.negative_similarity : null,
      ranked_by: hit ? 'embedding' : 'recency',
    },
  };
});

// Papers that overflowed the batch limit keep their place at the back rather
// than being dropped: a partial ranking must not silently lose papers.
ranked.sort((a, b) => (b.json.rank_score ?? -Infinity) - (a.json.rank_score ?? -Infinity));

return ranked;

